package io.github.windyzhu3.ontologylaw.api;
import io.github.windyzhu3.ontologylaw.execution.*;import io.github.windyzhu3.ontologylaw.identity.AuthorizationService.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class TransferRecoveryContractTest {
 CommandEnvelope command(String kind,boolean workflow){var opportunity=UUID.randomUUID();var source=Map.of("id",UUID.randomUUID().toString(),"revision",0L);var body=new LinkedHashMap<String,Object>();body.put("opportunityId",opportunity.toString());body.put("expectedOpportunityRevision",0L);body.put("responsibilityBasis",Map.of("id",opportunity.toString(),"revision",0L));body.put("sourceKind",kind);body.put("source",source);body.put("expectedWorkflow",workflow?source:null);return new CommandEnvelope(CommandEnvelope.Type.RECONCILE_CONTRACT_PREPARATION,UUID.randomUUID(),UUID.randomUUID(),new Actor(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),null,null,PrincipalKind.SERVICE),body);}
 @Test void transfer_handoff_uses_exact_execution_verification_and_has_no_prior_workflow(){var e=command("TRANSFER_HANDOFF",false);var b=R2ContractRecoveryCommand.input(e);assertEquals("contract.execution_verification",b.source().type());assertEquals("TRANSFER_HANDOFF",b.sourceKind());assertEquals("transfer.workflow",b.resultType());assertNull(b.workflow());assertEquals(ContractPreparationDiscovery.commandId(e.actor().tenantId(),b),ContractPreparationDiscovery.commandId(e.actor().tenantId(),b));}
 @Test void transfer_recovery_requires_the_exact_current_workflow_as_both_source_and_precondition(){var e=command("TRANSFER_RECOVERY",true);var b=R2ContractRecoveryCommand.input(e);assertEquals("transfer.workflow",b.source().type());assertEquals(b.source(),b.workflow());assertThrows(CommandHandler.Rejected.class,()->R2ContractRecoveryCommand.input(command("TRANSFER_RECOVERY",false)));assertThrows(CommandHandler.Rejected.class,()->R2ContractRecoveryCommand.input(command("TRANSFER_HANDOFF",true)));}
}
